#!/usr/bin/env python3
"""
Ledger — Trade Journal
------------------------
A focused, standalone trading journal. Log trades (stock/forex/crypto/
indice/future) with date, P&L, pattern, entry, exit, risk:reward, tags,
and a screenshot. See a stat overview and an equity curve of everything
you've logged.

No API key needed — this version doesn't pull any market data, so there's
nothing to configure. Just deploy and go.
"""

import base64
import json
import os
import uuid
from datetime import datetime
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

PORT = int(os.environ.get("PORT", 8000))
JOURNAL_FILE = "journal.json"

ICON_512_B64 = ""
ICON_192_B64 = ""
ICON_180_B64 = ""
SPLASH_BG_B64 = ""

JOURNAL = []


def load_journal():
    global JOURNAL
    if os.path.exists(JOURNAL_FILE):
        try:
            with open(JOURNAL_FILE, "r") as f:
                JOURNAL = json.load(f)
        except Exception:
            JOURNAL = []


def save_journal():
    try:
        with open(JOURNAL_FILE, "w") as f:
            json.dump(JOURNAL, f)
    except Exception:
        pass


